// @FIGURE_CODE_BEGIN
(function () {
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  var W = 860, H = 390;
  draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

  var COL = {
    fillQ: '#dcdcdc', fillTri: '#b2b2b2', hull: '#bdbdbd', chord: '#9a9a9a',
    accent: '#e8790c', accentFill: '#fbdcbb', pop: '#c0392b'
  };
  var SERIF = 'Georgia, "Times New Roman", Times, serif';

  // ---- geometry (panel a / panel b) -------------------------------------
  var A = {
    p0: [95, 252], pi: [40, 82], pj: [150, 28], pk: [240, 37],
    u1: [305, 63], u2: [352, 107], p2: [360, 160], p1: [330, 232]
  };
  var B = {
    p0: [535, 255], pi: [468, 85], pr: [545, 92], pt: [512, 122], pj: [600, 32],
    b1: [672, 42], b2: [742, 70], b3: [792, 112], b4: [802, 168], p1: [772, 228]
  };

  function pstr(list) {
    return list.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
  }
  function arcPts(c, from, to, r) {
    var a1 = Math.atan2(from[1] - c[1], from[0] - c[0]);
    var a2 = Math.atan2(to[1] - c[1], to[0] - c[0]);
    var d = a2 - a1;
    while (d > Math.PI) d -= 2 * Math.PI;
    while (d < -Math.PI) d += 2 * Math.PI;
    var out = [];
    for (var i = 0; i <= 26; i++) {
      var a = a1 + d * i / 26;
      out.push([c[0] + r * Math.cos(a), c[1] + r * Math.sin(a)]);
    }
    return out;
  }
  function halo(t) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
    return t;
  }

  // ---- layers ------------------------------------------------------------
  var gA = draw.group(), gB = draw.group(), hl = draw.group();
  var gLabA = draw.group(), gLabB = draw.group(), gMeta = draw.group(), stackG = draw.group();

  // ---- labels ------------------------------------------------------------
  function mkLabel(parent, base, sub, cx, cy, color) {
    var g = parent.group();
    var t = halo(g.text(base).font({ family: SERIF, size: 17, style: 'italic' }).fill(color || '#000'));
    t.move(0, 0);
    var w = t.bbox().width;
    if (sub) {
      var s = halo(g.text(sub).font({ family: SERIF, size: 11, style: 'italic' }).fill(color || '#000'));
      s.move(w + 1, 8);
    }
    g.center(cx, cy);
    return g;
  }
  function plainText(parent, str, cx, cy, size, color, italic) {
    var t = halo(parent.text(str).font({ family: SERIF, size: size, style: italic ? 'italic' : 'normal' }).fill(color));
    t.center(cx, cy);
    return t;
  }

  // ---- panel (a) base ----------------------------------------------------
  var Qpoly = [A.p0, A.pj, A.pk, A.u1, A.u2, A.p2, A.p1];
  var outerA = [A.p0, A.pi, A.pj, A.pk, A.u1, A.u2, A.p2, A.p1];

  var qShape = gA.polygon(pstr(Qpoly)).fill(COL.fillQ).stroke('none');
  var triShape = gA.polygon(pstr([A.p0, A.pj, A.pi])).fill(COL.fillTri).stroke('none');
  gA.polygon(pstr(outerA)).fill('none').stroke({ color: COL.hull, width: 6, linejoin: 'round' });
  gA.line(A.p0[0], A.p0[1], A.pj[0], A.pj[1]).stroke({ color: COL.chord, width: 1.2 });

  qShape.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Q\u2c7c — the convex hull of the points processed so far', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Q\u2c7c: the hull so far', 'Q\u2c7c is the convex hull of the points already accepted, read counterclockwise off the stack from p\u2080 up to p\u2c7c. Every accepted point is a corner of this polygon.'); });
  triShape.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('triangle p\u2080 p\u2c7c p\u1d62 — annexed when p\u1d62 is pushed', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('The annexed triangle', 'Because the turn p\u2080 \u2192 p\u2c7c \u2192 p\u1d62 is a left turn, p\u1d62 lies outside Q\u2c7c. Pushing p\u1d62 adds exactly the darker triangle p\u2080 p\u2c7c p\u1d62 to the hull.'); });

  // ---- panel (b) base ----------------------------------------------------
  var chainB = [B.p0, B.p1, B.b4, B.b3, B.b2, B.b1, B.pj];
  gB.polyline(pstr(chainB)).fill('none')
    .stroke({ color: COL.hull, width: 6, linecap: 'round', linejoin: 'round' });
  var triB = gB.polygon(pstr([B.pi, B.pr, B.p0])).fill('#dcdcdc').stroke({ color: '#000', width: 1 });
  gB.line(B.pi[0], B.pi[1], B.pt[0], B.pt[1]).stroke({ color: '#000', width: 1, dasharray: '3,3' });
  gB.line(B.pr[0], B.pr[1], B.pt[0], B.pt[1]).stroke({ color: '#000', width: 1, dasharray: '3,3' });
  gB.polyline(pstr(arcPts(B.pt, B.pi, B.pr, 17))).fill('none').stroke({ color: '#000', width: 1 });

  triB.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('triangle p\u1d62 p\u1d63 p\u2080 — all three corners are hull points', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { setFocus('B.pt'); });

  // ---- dots --------------------------------------------------------------
  function addDot(g, p, tip, focusKey) {
    var c = g.circle(9).center(p[0], p[1]).fill('#000');
    c.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', hideTooltip);
    if (focusKey) c.on('click', function () { setFocus(focusKey); });
    else c.on('click', function () { showPopup('Hull vertex', 'This point is already on the stack and, so far, is a corner of the hull. It will be popped only if a later candidate makes the turn through it nonleft.'); });
    return c;
  }

  addDot(gA, A.p0, 'p\u2080 — the anchor (lowest point); always on the hull', null);
  addDot(gA, A.pj, 'p\u2c7c — current top of the stack', 'A.pj');
  addDot(gA, A.pi, 'p\u1d62 — candidate: left turn \u21d2 push', 'A.pi');
  addDot(gA, A.pk, 'p\u2096 — hull vertex on the stack', null);
  addDot(gA, A.u1, 'hull vertex on the stack', null);
  addDot(gA, A.u2, 'hull vertex on the stack', null);
  addDot(gA, A.p2, 'p\u2082 — hull vertex on the stack', null);
  addDot(gA, A.p1, 'p\u2081 — hull vertex on the stack', null);

  addDot(gB, B.p0, 'p\u2080 — the anchor; a corner of the enclosing triangle', null);
  addDot(gB, B.pj, 'p\u2c7c — hull vertex', null);
  addDot(gB, B.b1, 'hull vertex', null);
  addDot(gB, B.b2, 'hull vertex', null);
  addDot(gB, B.b3, 'hull vertex', null);
  addDot(gB, B.b4, 'hull vertex', null);
  addDot(gB, B.p1, 'p\u2081 — hull vertex', null);
  addDot(gB, B.pi, 'p\u1d62 — next-to-top of the stack', null);
  addDot(gB, B.pr, 'p\u1d63 — candidate: turn at p\u209c is nonleft', 'B.pr');
  addDot(gB, B.pt, 'p\u209c — top of stack, trapped inside triangle p\u1d62 p\u1d63 p\u2080', 'B.pt');

  // ---- labels ------------------------------------------------------------
  mkLabel(gLabA, 'p', 'i', 18, 72);
  mkLabel(gLabA, 'p', 'j', 146, 10);
  mkLabel(gLabA, 'p', 'k', 254, 18);
  mkLabel(gLabA, 'p', '2', 382, 168);
  mkLabel(gLabA, 'p', '1', 352, 248);
  mkLabel(gLabA, 'p', '0', 86, 278);
  mkLabel(gLabA, 'Q', 'j', 240, 132);

  mkLabel(gLabB, 'p', 'i', 444, 80);
  mkLabel(gLabB, 'p', 'r', 568, 88);
  mkLabel(gLabB, 'p', 't', 512, 145);
  mkLabel(gLabB, 'p', 'j', 592, 12);
  mkLabel(gLabB, 'p', '1', 792, 244);
  mkLabel(gLabB, 'p', '0', 528, 280);

  plainText(gMeta, '(a)', 200, 336, 15, '#000', false);
  plainText(gMeta, '(b)', 648, 336, 15, '#000', false);

  // ---- state -------------------------------------------------------------
  var scanStates = ['start', 'test p_j p_i', 'push p_i', 'test p_i p_r p_t', 'pop p_t', 'done'];
  var scanIdx = 0;
  var caseValue = '(a) left turn — push';
  var caseTouched = false;
  var focusKey = null;

  function ring(p, color, r) {
    hl.circle(r || 12).center(p[0], p[1]).fill('#fff').stroke({ color: color, width: 2.5 });
  }

  function hlTestA() {
    hl.polyline(pstr([A.p0, A.pj, A.pi])).fill('none')
      .stroke({ color: COL.accent, width: 3.2, linecap: 'round', linejoin: 'round' });
    hl.polyline(pstr(arcPts(A.pj, A.p0, A.pi, 27))).fill('none').stroke({ color: COL.accent, width: 2 });
    ring(A.p0, COL.accent); ring(A.pj, COL.accent); ring(A.pi, COL.accent);
  }
  function hlPushA() {
    hl.polygon(pstr([A.p0, A.pj, A.pi])).fill(COL.accentFill).opacity(0.85)
      .stroke({ color: COL.accent, width: 2, dasharray: '5,4', linejoin: 'round' });
    hl.polyline(pstr([A.p0, A.pi, A.pj])).fill('none').opacity(0.9)
      .stroke({ color: COL.accent, width: 5, linecap: 'round', linejoin: 'round' });
    ring(A.pi, COL.accent);
  }
  function hlTestB() {
    hl.line(B.pi[0], B.pi[1], B.pt[0], B.pt[1])
      .stroke({ color: COL.accent, width: 2.4, dasharray: '5,4', linecap: 'round' });
    hl.line(B.pr[0], B.pr[1], B.pt[0], B.pt[1])
      .stroke({ color: COL.accent, width: 2.4, dasharray: '5,4', linecap: 'round' });
    hl.polyline(pstr(arcPts(B.pt, B.pi, B.pr, 18))).fill('none').stroke({ color: COL.accent, width: 2.2 });
    ring(B.pi, COL.accent); ring(B.pr, COL.accent); ring(B.pt, COL.accent);
  }
  function hlPopB() {
    hl.polygon(pstr([B.pi, B.pr, B.p0])).fill(COL.accentFill).opacity(0.85)
      .stroke({ color: COL.accent, width: 2, dasharray: '5,4', linejoin: 'round' });
    [B.pi, B.pr, B.p0].forEach(function (p) {
      hl.line(B.pt[0], B.pt[1], p[0], p[1])
        .stroke({ color: COL.pop, width: 1.4, dasharray: '4,4' }).opacity(0.85);
    });
    ring(B.pt, COL.pop, 14);
    hl.line(B.pt[0] - 4, B.pt[1] - 4, B.pt[0] + 4, B.pt[1] + 4).stroke({ color: COL.pop, width: 2 });
    hl.line(B.pt[0] - 4, B.pt[1] + 4, B.pt[0] + 4, B.pt[1] - 4).stroke({ color: COL.pop, width: 2 });
    ring(B.pi, COL.accent); ring(B.pr, COL.accent);
  }
  function hlFocus() {
    if (focusKey === 'A.pi') {
      hl.polygon(pstr([A.p0, A.pj, A.pi])).fill('none')
        .stroke({ color: COL.accent, width: 2.6, dasharray: '6,4', linejoin: 'round' });
      ring(A.pi, COL.accent);
    } else if (focusKey === 'A.pj') {
      hl.line(A.p0[0], A.p0[1], A.pj[0], A.pj[1]).stroke({ color: COL.accent, width: 3.2 });
      ring(A.pj, COL.accent); ring(A.p0, COL.accent);
    } else if (focusKey === 'B.pr') {
      hl.polygon(pstr([B.pi, B.pr, B.p0])).fill('none')
        .stroke({ color: COL.accent, width: 2.6, dasharray: '6,4', linejoin: 'round' });
      ring(B.pr, COL.accent);
    } else if (focusKey === 'B.pt') {
      hl.polygon(pstr([B.pi, B.pr, B.p0])).fill('none')
        .stroke({ color: COL.accent, width: 2.6, dasharray: '6,4', linejoin: 'round' });
      [B.pi, B.pr, B.p0].forEach(function (p) {
        hl.line(B.pt[0], B.pt[1], p[0], p[1]).stroke({ color: COL.pop, width: 1.3, dasharray: '4,4' });
      });
      ring(B.pt, COL.pop, 14);
    }
  }

  var POPUPS = {
    'A.pi': ['p\u1d62 is pushed', 'p\u1d62 is the next candidate. The turn p\u2080 \u2192 p\u2c7c \u2192 p\u1d62 is a LEFT turn, so p\u1d62 lies outside the current hull Q\u2c7c. It is pushed, and the hull grows by exactly the triangle p\u2080 p\u2c7c p\u1d62.'],
    'A.pj': ['p\u2c7c stays on the stack', 'p\u2c7c is the current top of the stack. Because the turn through it bends left, p\u2c7c is still a corner of the enlarged boundary and is not popped.'],
    'B.pr': ['p\u1d63 is the candidate', 'p\u1d63 is the point now being tested. Together with p\u1d62 (next-to-top of the stack) and the anchor p\u2080, it forms a triangle whose three corners are all hull points \u2014 and p\u209c lies inside it.'],
    'B.pt': ['p\u209c is popped', 'The turn p\u1d62 \u2192 p\u209c \u2192 p\u1d63 is nonleft, which places p\u209c strictly inside triangle p\u1d62 p\u1d63 p\u2080. All three corners are hull points, so p\u209c can never be a vertex of the convex hull and is popped.']
  };

  window.setFocus = function (key) {
    focusKey = (focusKey === key) ? null : key;
    if (focusKey && POPUPS[key]) showPopup(POPUPS[key][0], POPUPS[key][1]);
    render();
  };

  function stackLine() {
    var aStack = (scanIdx >= 2) ? 'p0 p1 p2 · · pk pj pi' : 'p0 p1 p2 · · pk pj';
    var aNote = (scanIdx === 1) ? '   testing pi' : (scanIdx === 2 || scanIdx === 5 ? '   pi pushed' : '');
    var bStack = (scanIdx >= 4) ? 'p0 · · pi' : 'p0 · · pi pt';
    var bNote = (scanIdx === 3) ? '   testing pr' : (scanIdx >= 4 ? '   pt popped' : '');
    return [
      '(a) stack ↑: ' + aStack + aNote,
      '(b) stack ↑: ' + bStack + bNote
    ];
  }

  function render() {
    hl.clear(); stackG.clear();
    var s = scanStates[scanIdx];
    var emphasize = caseTouched || s !== 'start';

    var dimA = emphasize && caseValue.charAt(1) === 'b';
    var dimB = emphasize && caseValue.charAt(1) === 'a';
    gA.opacity(dimA ? 0.3 : 1); gLabA.opacity(dimA ? 0.3 : 1);
    gB.opacity(dimB ? 0.3 : 1); gLabB.opacity(dimB ? 0.3 : 1);

    if (s === 'test p_j p_i') hlTestA();
    if (s === 'push p_i') hlPushA();
    if (s === 'test p_i p_r p_t') hlTestB();
    if (s === 'pop p_t') hlPopB();
    if (s === 'done') { hlPushA(); hlPopB(); }
    hlFocus();

    if (s !== 'start') {
      var lines = stackLine();
      var t1 = stackG.text(lines[0]).font({ family: 'ui-monospace, Consolas, monospace', size: 11 }).fill('#555');
      t1.move(40, 352);
      var t2 = stackG.text(lines[1]).font({ family: 'ui-monospace, Consolas, monospace', size: 11 }).fill('#555');
      t2.move(470, 352);
    }

    var out = document.getElementById('scanStateOut');
    if (out) out.textContent = s;
    var so = document.getElementById('stackOut');
    if (so) so.innerHTML = stackLine().join('<br>');
  }

  // ---- controls ----------------------------------------------------------
  window.toggle_caseToggle = function (v) {
    caseValue = v; caseTouched = true; render();
  };
  window.trigger_scanStep = function () {
    scanIdx = (scanIdx + 1) % scanStates.length;
    if (scanIdx >= 3 && scanIdx <= 4) caseValue = '(b) nonleft turn — pop';
    else if (scanIdx >= 1 && scanIdx <= 2) caseValue = '(a) left turn — push';
    else if (scanIdx === 5) caseValue = 'both panels';
    caseTouched = true;
    var sel = document.getElementById('caseToggleInput');
    if (sel) sel.value = caseValue;
    render();
  };
  window.trigger_resetScan = function () {
    scanIdx = 0; focusKey = null; caseTouched = false;
    caseValue = '(a) left turn — push';
    var sel = document.getElementById('caseToggleInput');
    if (sel) sel.value = caseValue;
    render();
  };

  // ---- demo steps --------------------------------------------------------
  var steps = [
    { title: 'The hull so far', narration: 'The light gray polygon Q\u2c7c is the convex hull of the points processed so far, with p\u2080 at the bottom and the stack running counterclockwise to p\u2c7c. Everything already accepted is a vertex of this shape.', state: { caseToggle: '(a) left turn — push', scanStep: 'start' } },
    { title: 'Testing a left turn', narration: 'The next candidate p\u1d62 is tested against the top two stack points. The turn from p\u2080\u2192p\u2c7c to p\u2c7c\u2192p\u1d62 is a left turn, so p\u1d62 lies outside the current hull.', state: { caseToggle: '(a) left turn — push', scanStep: 'test p_j p_i' } },
    { title: 'Push: the hull grows', narration: 'p\u1d62 is pushed onto the stack and the dark triangle p\u2080\u2013p\u2c7c\u2013p\u1d62 is annexed to Q\u2c7c. The boundary now detours through p\u1d62, showing that a left turn strictly enlarges the hull.', state: { caseToggle: '(a) left turn — push', scanStep: 'push p_i' } },
    { title: 'A nonleft turn', narration: 'Switch to panel (b). Here the angle at p\u209c formed by p\u1d62, p\u209c, p\u1d63 is not a left turn — the dashed segments and the arc show p\u209c bending the wrong way.', state: { caseToggle: '(b) nonleft turn — pop', scanStep: 'test p_i p_r p_t' } },
    { title: 'Pop: the point was never a vertex', narration: 'Because the turn is nonleft, p\u209c lies inside triangle p\u1d62 p\u1d63 p\u2080, whose three corners are all hull points. A point interior to a triangle of hull points cannot be a hull vertex, so p\u209c is popped.', state: { caseToggle: '(b) nonleft turn — pop', scanStep: 'pop p_t' } },
    { title: 'Two cases, one test', narration: 'Side by side, the panels show the invariant: every candidate either extends the boundary outward or reveals an earlier point as interior. Nothing else can happen.', state: { caseToggle: 'both panels', scanStep: 'done' } }
  ];
  var stepIdx = 0;

  function applyStep(i) {
    stepIdx = Math.max(0, Math.min(steps.length - 1, i));
    var st = steps[stepIdx].state;
    caseValue = st.caseToggle;
    scanIdx = scanStates.indexOf(st.scanStep);
    caseTouched = false;
    focusKey = null;
    var sel = document.getElementById('caseToggleInput');
    if (sel) sel.value = caseValue;
    var tt = document.getElementById('demoTitle');
    if (tt) tt.textContent = steps[stepIdx].title;
    var nn = document.getElementById('demoNarration');
    if (nn) nn.textContent = steps[stepIdx].narration;
    var sl = document.getElementById('stepLabel');
    if (sl) sl.textContent = 'step ' + (stepIdx + 1) + ' / ' + steps.length;
    render();
  }
  window.nextStep = function () { applyStep(stepIdx + 1); };
  window.prevStep = function () { applyStep(stepIdx - 1); };

  applyStep(0);
  window.__markRendered();
})();
